package walk.cosmic.debug;

import kd.cosmic.debug.tools.CosmicLauncher;

/**
 * 启动本地应用程序(微服务节点)
 */
public class DebugApplication {

    public static void main(String[] args) {
    	
//    	Thread.currentThread().setContextClassLoader(new KDSecurityClassLoader(Thread.currentThread().getContextClassLoader()));
    	
        // 使用远程环境配置，避免本地默认地址覆盖 MC 中的服务配置。
        CosmicLauncher cosmic = new CosmicLauncher(true);

        cosmic.setClusterNumber("cosmic");
        cosmic.setTenantNumber("ierp");
        
//        cosmic.setConfigUrl("127.0.0.1:2181?user=zookeeper&password=xxx");
        cosmic.setConfigUrl("192.168.0.187:2181?user=zookeeper&password=Cosmic2020");
        String remoteZookeeperUrl = cosmic.get("configUrl");
        String remoteZookeeperAddress = remoteZookeeperUrl.replace("?", "/?");
        cosmic.set("dubbo.registry.address", remoteZookeeperUrl);
        cosmic.set("dubbo.zookeeper.ip_port", remoteZookeeperAddress);
        cosmic.set("Schedule.zk.server.ip_port", remoteZookeeperAddress);
        
//        cosmic.setMcServerUrl("http://127.0.0.1:8090");
        cosmic.setMcServerUrl("http://192.168.0.187:8090/"); 
        
//        cosmic.setFsServerUrl("127.0.0.1", 8100);
//        cosmic.setImageServerUrl("127.0.0.1", 8100);
        
        // 自定义本地苍穹调试服务的端口
        cosmic.setCosmicWebPort(8881);

        // 跨应用调用优先查找本地进程内服务，避免请求被路由到公司云端实例执行
        // （lookup.local=false 时会模拟分布式：调用走远程 ZK 订阅到的 provider，导致预览在云端执行、找不到本地插件类）
        cosmic.set("dubbo.service.lookup.local", "true");

        cosmic.start();
    }
}
